// Try 阶段：预留资源
public boolean tryDeductStock(String orderId, int count) {
    // 冻结库存（不实际扣减）
    int rows = jdbc.update(
        "UPDATE products SET frozen = frozen + ? WHERE id = 1 AND stock - frozen >= ?",
        count, count);
    return rows > 0;
}

// Confirm 阶段：真正扣减
public boolean confirmDeductStock(String orderId, int count) {
    int rows = jdbc.update(
        "UPDATE products SET stock = stock - ?, frozen = frozen - ? WHERE id = 1",
        count, count);
    return rows > 0;
}

// Cancel 阶段：释放冻结
public boolean cancelDeductStock(String orderId, int count) {
    int rows = jdbc.update(
        "UPDATE products SET frozen = frozen - ? WHERE id = 1", count);
    return rows > 0;
}

// 按 user_id 分 16 个库，每库 16 张表（共 256 张表）
public class ShardingRouter {
    private static final int DB_COUNT = 16;
    private static final int TABLE_COUNT_PER_DB = 16;

    public String routeDb(long userId) {
        int dbIndex = (int) (userId % DB_COUNT);
        return "db_" + dbIndex;
    }

    public String routeTable(long userId) {
        int tableIndex = (int) ((userId / DB_COUNT) % TABLE_COUNT_PER_DB);
        return "orders_" + tableIndex;
    }
}

