// 跨分片查询：广播 + 归并
public List<Order> getOrdersByTime(LocalDate date) {
    List<Order> results = new ArrayList<>();
    for (int db = 0; db < DB_COUNT; db++) {
        for (int table = 0; table < TABLE_COUNT_PER_DB; table++) {
            results.addAll(queryShard(db, table, date));
        }
    }
    return results;
}

-- 慢：OFFSET 1000000 会扫描并丢弃前 100 万行
SELECT * FROM orders ORDER BY id LIMIT 1000000, 10;

-- 快：游标方式（记录上次的 id）
SELECT * FROM orders WHERE id > 1000000 ORDER BY id LIMIT 10;

-- 如果必须跳页：先查 id 再回表
SELECT o.* FROM orders o
INNER JOIN (
  SELECT id FROM orders ORDER BY id LIMIT 1000000, 10
) t ON o.id = t.id;
-- 子查询用覆盖索引，不回表；主查询只回表 10 次

-- 方法 1：用窗口函数标记后删除
DELETE FROM users
WHERE id IN (
  SELECT id FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY email ORDER BY id) AS rn
    FROM users
  ) t WHERE rn > 1
);

-- 方法 2：用自连接
DELETE u1 FROM users u1
INNER JOIN users u2 ON u1.email = u2.email AND u1.id > u2.id;
